IF FirstScan THEN
    Fv_3_3040_Out := 6554;
    Fv_3_3041_Out := 6554;
    FT_10_Integral := 0.0;
    FT_11_Integral := 0.0;
    FT_10_HH_Latch.S1 := FALSE;
    FT_10_HH_Latch.R  := FALSE;
    FT_10_LL_Latch.S1 := FALSE;
    FT_10_LL_Latch.R  := FALSE;
    FT_11_HH_Latch.S1 := FALSE;
    FT_11_HH_Latch.R  := FALSE;
    FT_11_LL_Latch.S1 := FALSE;
    FT_11_LL_Latch.R  := FALSE;
    FT_10_HH_Latch(S1 := FALSE, R := FALSE);
    FT_10_LL_Latch(S1 := FALSE, R := FALSE);
    FT_11_HH_Latch(S1 := FALSE, R := FALSE);
    FT_11_LL_Latch(S1 := FALSE, R := FALSE);
    FirstScan := FALSE;
    RETURN;
END_IF;

FT_10_Scaled := ((INT_TO_REAL(FT_10_Raw) - 6554.0) / (32767.0 - 6554.0)) * 100.0;
FT_11_Scaled := ((INT_TO_REAL(FT_11_Raw) - 6554.0) / (32767.0 - 6554.0)) * 100.0;

(* FT-10 HH latch — set above HH_SP, clear below deadband when acknowledged *)
IF FT_10_Scaled >= FT_10_HH_SP THEN
    FT_10_HH_Latch.S1 := TRUE;
ELSIF FT_10_Scaled <= (FT_10_HH_SP - FT_10_Deadband) THEN
    FT_10_HH_Latch.S1 := FALSE;
END_IF;
FT_10_HH_Latch.R := FT_10_HH_Ack AND (FT_10_Scaled < FT_10_HH_SP);
FT_10_HH_Latch(S1 := FT_10_HH_Latch.S1, R := FT_10_HH_Latch.R);

(* FT-10 H alarm with deadband *)
IF FT_10_Scaled >= FT_10_H_SP THEN
    FT_10_H := TRUE;
ELSIF FT_10_Scaled <= (FT_10_H_SP - FT_10_Deadband) THEN
    FT_10_H := FALSE;
END_IF;

(* FT-10 L alarm with deadband *)
IF FT_10_Scaled <= FT_10_L_SP THEN
    FT_10_L := TRUE;
ELSIF FT_10_Scaled >= (FT_10_L_SP + FT_10_Deadband) THEN
    FT_10_L := FALSE;
END_IF;

(* FT-10 LL latch — set below LL_SP, clear above deadband when acknowledged *)
IF FT_10_Scaled <= FT_10_LL_SP THEN
    FT_10_LL_Latch.S1 := TRUE;
ELSIF FT_10_Scaled >= (FT_10_LL_SP + FT_10_Deadband) THEN
    FT_10_LL_Latch.S1 := FALSE;
END_IF;
FT_10_LL_Latch.R := FT_10_LL_Ack AND (FT_10_Scaled > FT_10_LL_SP);
FT_10_LL_Latch(S1 := FT_10_LL_Latch.S1, R := FT_10_LL_Latch.R);

(* FT-11 HH latch *)
IF FT_11_Scaled >= FT_11_HH_SP THEN
    FT_11_HH_Latch.S1 := TRUE;
ELSIF FT_11_Scaled <= (FT_11_HH_SP - FT_11_Deadband) THEN
    FT_11_HH_Latch.S1 := FALSE;
END_IF;
FT_11_HH_Latch.R := FT_11_HH_Ack AND (FT_11_Scaled < FT_11_HH_SP);
FT_11_HH_Latch(S1 := FT_11_HH_Latch.S1, R := FT_11_HH_Latch.R);

(* FT-11 H alarm with deadband *)
IF FT_11_Scaled >= FT_11_H_SP THEN
    FT_11_H := TRUE;
ELSIF FT_11_Scaled <= (FT_11_H_SP - FT_11_Deadband) THEN
    FT_11_H := FALSE;
END_IF;

(* FT-11 L alarm with deadband *)
IF FT_11_Scaled <= FT_11_L_SP THEN
    FT_11_L := TRUE;
ELSIF FT_11_Scaled >= (FT_11_L_SP + FT_11_Deadband) THEN
    FT_11_L := FALSE;
END_IF;

(* FT-11 LL latch *)
IF FT_11_Scaled <= FT_11_LL_SP THEN
    FT_11_LL_Latch.S1 := TRUE;
ELSIF FT_11_Scaled >= (FT_11_LL_SP + FT_11_Deadband) THEN
    FT_11_LL_Latch.S1 := FALSE;
END_IF;
FT_11_LL_Latch.R := FT_11_LL_Ack AND (FT_11_Scaled > FT_11_LL_SP);
FT_11_LL_Latch(S1 := FT_11_LL_Latch.S1, R := FT_11_LL_Latch.R);

(* FT-10 PI controller driving Fv-3-3040 *)
FT_10_Error := FT_10_SP - FT_10_Scaled;
FT_10_Integral := FT_10_Integral + (FT_10_Ki * FT_10_Error);
IF FT_10_Integral > 100.0 THEN
    FT_10_Integral := 100.0;
ELSIF FT_10_Integral < 0.0 THEN
    FT_10_Integral := 0.0;
END_IF;
FT_10_Output := (FT_10_Kp * FT_10_Error) + FT_10_Integral;
IF FT_10_Output > 100.0 THEN
    FT_10_Output := 100.0;
ELSIF FT_10_Output < 0.0 THEN
    FT_10_Output := 0.0;
END_IF;
Fv_3_3040_Out := REAL_TO_INT(6554.0 + (FT_10_Output / 100.0) * (32767.0 - 6554.0));

(* FT-11 PI controller driving Fv-3-3041 *)
FT_11_Error := FT_11_SP - FT_11_Scaled;
FT_11_Integral := FT_11_Integral + (FT_11_Ki * FT_11_Error);
IF FT_11_Integral > 100.0 THEN
    FT_11_Integral := 100.0;
ELSIF FT_11_Integral < 0.0 THEN
    FT_11_Integral := 0.0;
END_IF;
FT_11_Output := (FT_11_Kp * FT_11_Error) + FT_11_Integral;
IF FT_11_Output > 100.0 THEN
    FT_11_Output := 100.0;
ELSIF FT_11_Output < 0.0 THEN
    FT_11_Output := 0.0;
END_IF;
Fv_3_3041_Out := REAL_TO_INT(6554.0 + (FT_11_Output / 100.0) * (32767.0 - 6554.0));

System_Alarm :=
    FT_10_HH_Latch.Q1 OR FT_10_LL_Latch.Q1 OR
    FT_10_H           OR FT_10_L            OR
    FT_11_HH_Latch.Q1 OR FT_11_LL_Latch.Q1 OR
    FT_11_H           OR FT_11_L;
